   if(open.length<o||multi.length<c)return {error:'Недостаточно заданий для раздела «'+section+'»: нужно '+o+' открытых и '+c+' с несколькими верными вариантами, доступно '+open.length+' и '+multi.length+'. Измените набор вопросов. Задания с одним ответом не заменяют multiple choice.'};
   selected.push(...shuffle(open).slice(0,o),...shuffle(multi).slice(0,c));
